import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"3、【屯】 震下坎上","description":"横渠易说 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"横渠易说 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/005.md","filePath":"zh/classics/hengqu/005.md"}'),l={name:"zh/classics/hengqu/005.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><h3 id="彖曰-屯-刚柔始交而难生-动乎险中-大亨贞。雷雨之动满盈-天造草昧-宜建侯而不宁。" tabindex="-1">彖曰：屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。 <a class="header-anchor" href="#彖曰-屯-刚柔始交而难生-动乎险中-大亨贞。雷雨之动满盈-天造草昧-宜建侯而不宁。" aria-label="Permalink to “彖曰：屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。”">​</a></h3><p>往则失其居矣。</p><h3 id="象曰-云雷屯-君子以经纶。" tabindex="-1">象曰：云雷屯，君子以经纶。 <a class="header-anchor" href="#象曰-云雷屯-君子以经纶。" aria-label="Permalink to “象曰：云雷屯，君子以经纶。”">​</a></h3><p>云雷皆是气之聚处，屯，聚也。</p><h3 id="初九-磐桓-利居贞-利建侯。-象曰-虽磐桓-志行正也。以贵下贱-大得民也。" tabindex="-1">初九，磐桓，利居贞，利建侯。 象曰：虽磐桓，志行正也。以贵下贱，大得民也。 <a class="header-anchor" href="#初九-磐桓-利居贞-利建侯。-象曰-虽磐桓-志行正也。以贵下贱-大得民也。" aria-label="Permalink to “初九，磐桓，利居贞，利建侯。 象曰：虽磐桓，志行正也。以贵下贱，大得民也。”">​</a></h3><p>磐桓犹言柱石。磐，磐石也；桓，桓柱也；谓利建侯，如柱石在下不可以动，然志在行正也。</p><h3 id="六二-屯如邅如-乘马班如-匪寇婚媾。女子贞不字-十年乃字。-象曰-六二之难-乘刚也。-十年乃字-反常也。" tabindex="-1">六二，屯如邅如，乘马班如，匪寇婚媾。女子贞不字，十年乃字。 象曰：六二之难，乘刚也。“十年乃字”，反常也。 <a class="header-anchor" href="#六二-屯如邅如-乘马班如-匪寇婚媾。女子贞不字-十年乃字。-象曰-六二之难-乘刚也。-十年乃字-反常也。" aria-label="Permalink to “六二，屯如邅如，乘马班如，匪寇婚媾。女子贞不字，十年乃字。 象曰：六二之难，乘刚也。“十年乃字”，反常也。”">​</a></h3><p>班，布，不进之貌。</p><h3 id="六三-即鹿无虞-惟入于林中-君子几不如舍-往吝。-象曰-即鹿无虞-以从禽也。君子舍之-往吝穷也。" tabindex="-1">六三，即鹿无虞，惟入于林中，君子几不如舍，往吝。 象曰：“即鹿无虞”，以从禽也。君子舍之，往吝穷也。 <a class="header-anchor" href="#六三-即鹿无虞-惟入于林中-君子几不如舍-往吝。-象曰-即鹿无虞-以从禽也。君子舍之-往吝穷也。" aria-label="Permalink to “六三，即鹿无虞，惟入于林中，君子几不如舍，往吝。 象曰：“即鹿无虞”，以从禽也。君子舍之，往吝穷也。”">​</a></h3><p>处非其地，故曰“入于林中”。虞，防禁也。二以乘刚有寇，故五若可亲；五屯其膏，故不若舍之。</p><h3 id="六四-乘马班如-求婚媾-往吉-无不利。-象曰-求而往-明也。" tabindex="-1">六四，乘马班如，求婚媾，往吉，无不利。 象曰：求而往，明也。 <a class="header-anchor" href="#六四-乘马班如-求婚媾-往吉-无不利。-象曰-求而往-明也。" aria-label="Permalink to “六四，乘马班如，求婚媾，往吉，无不利。 象曰：求而往，明也。”">​</a></h3><h3 id="九五-屯其膏-小贞吉-大贞凶。-象曰-屯其膏-施未光也。" tabindex="-1">九五，屯其膏，小贞吉，大贞凶。 象曰：“屯其膏”，施未光也。 <a class="header-anchor" href="#九五-屯其膏-小贞吉-大贞凶。-象曰-屯其膏-施未光也。" aria-label="Permalink to “九五，屯其膏，小贞吉，大贞凶。 象曰：“屯其膏”，施未光也。”">​</a></h3><h3 id="上六-乘马班如-泣血涟如。-象曰-泣血涟如-何可长也" tabindex="-1">上六，乘马班如，泣血涟如。 象曰：“泣血涟如”，何可长也! <a class="header-anchor" href="#上六-乘马班如-泣血涟如。-象曰-泣血涟如-何可长也" aria-label="Permalink to “上六，乘马班如，泣血涟如。 象曰：“泣血涟如”，何可长也!”">​</a></h3><p>待求而往。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
